import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { buildRootStylesheet } from "../lib/buildRootStylesheet.js";
const here = dirname(fileURLToPath(import.meta.url));
const stylesheet = buildRootStylesheet();
const packageRoot = join(here, "..", "..");
const srcTokens = join(packageRoot, "src", "tokens.css");
writeFileSync(srcTokens, stylesheet, "utf8");
const distOut = join(packageRoot, "dist", "mercflow-tokens.css");
writeFileSync(distOut, stylesheet, "utf8");
